REVIEWED = '2026-09-05'

def entry(slug, name, category, route, linux, status, summary, needs, steps, trouble, sources, related=()):
    return dict(slug=slug, name=name, category=category, route=route, linux=linux,
                status=status, summary=summary, needs=needs, steps=steps,
                trouble=trouble, sources=sources, related=list(related), reviewed=REVIEWED)

