def crypto(slug, name, route, fact, source, status='planned', detail=None, steps=None, trouble=None):
    return entry(slug,name,'Crypto exchanges',route,'Cross-platform market-data API',status,fact,
      ['A supported Alpharch adapter for this exchange and product.','Regional availability and the provider’s current data-use conditions.'],
      steps or [('Choose the exact market','Keep spot, perpetuals and dated futures distinct. The same ticker can represent different instruments.'),('Use public data when supported','Public market-data channels do not require linking a trading account. Private account features use a separate authorization path.'),('Check Alpharch availability', detail or 'This exchange has not been integrated into Alpharch. The documented API is a development route, not a working connection in the current release.')],
      trouble or [('Price differs from another venue','Check the exchange, product, quote currency and contract. Do not substitute another exchange’s price.'),('Connection unavailable in your region','Use a provider available to you. Do not bypass regional access restrictions.')],
      [(name+' official API documentation',source)])

